#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Scripting : 1
COMPONENT Networking : 3

Viewpoint { }

NavigationInfo {
  type "NONE"
}

DirectionalLight {
  direction -0.4 -0.6 -1
}

DEF I Transform {
  translation -2.5 1.5 0
  children DEF IN Inline {
    url "browser-options-assets/blue.wrl"
  }
}

Transform {
  translation 2.5 1.5 0
  children Shape {
    appearance Appearance {
      texture DEF TEX ImageTexture {
        url "../synthetic-rea-render2/checker8.png"
      }
    }
    geometry Box { }
  }
}

DEF ROOT Transform {
  translation 0 -2 0
  children [
    DEF _1 Transform {
      translation -1.5 0 0
      children Inline {
        global TRUE
        url "browser-options-assets/blue.wrl"
      }
    }
    DEF _2 Script {
      url "ecmascript: function initialize () { print ('new script ran'); }"
    }
  ]
}

DEF S Script {
  inputOutput SFInt32  step 2
  inputOnly   SFTime   cycle
  inputOutput SFString hist "opt=false"
  inputOutput SFNode   inline USE IN
  inputOutput SFNode   tex USE TEX
  inputOutput SFNode   root USE ROOT

  url "ecmascript:
    function cycle (v) {
      step = step + 1;
      if (step == 2) {
        Browser .setBrowserOption ('LoadUrlObjects', false);
        hist = 'opt=' + Browser .getBrowserOption ('LoadUrlObjects');
        inline .url = new MFString ('browser-options-assets/blue.wrl');
        tex .url = new MFString ('../synthetic-rea-render2/checker8.png');
        var n = Browser .createVrmlFromString ('Transform { translation -1.5 0 0 children Inline { url \"browser-options-assets/blue.wrl\" } } Script { url \"ecmascript: function initialize () { print (\\'new script ran\\'); }\" }');
        root .children = n;
      }
      if (step == 4) {
        Browser .setBrowserOption ('LoadUrlObjects', true);
      }
      if (step == 6) {
        inline .url = new MFString ('browser-options-assets/blue.wrl', 'x.wrl');
      }
    }
  "
}

DEF STEP TimeSensor {
  cycleInterval 0.25
  loop TRUE
}

ROUTE STEP.cycleTime TO S.cycle

